        def check_rows():
            for row in grid:
                if len(set(row)) < 7:
                    return False
            return True

        def check_cols():
            for col in range(9):
                if len(set(grid[row][col] for row in range(9))) < 7:
                    return False
            return True

        def check_blocks():
            for block_row in range(0, 9, 3):
                for block_col in range(0, 9, 3):
                    block = set()
                    for r in range(block_row, block_row + 3):
                        for c in range(block_col, block_col + 3):
                            block.add(grid[r][c])
                    if len(block) < 7:
                        return False
            return True

        return check_rows() and check_cols() and check_blocks()

    def create_anti_sudoku(grid):
        # Start with a copy of the original grid
        anti_sudoku = [row[:] for row in grid]

        # Change at most 9 elements to create anti-sudoku
        changes = 0
        for i in range(9):
            for j in range(9):
                if changes >= 9:
                    return anti_sudoku

                # Try to place a number that will make the row, column, or block invalid
                original = anti_sudoku[i][j]
                for num in range(1, 10):
                    if num != original:
                        anti_sudoku[i][j] = num
                        if is_valid_anti_sudoku(anti_sudoku):
                            changes += 1
                            break
                else:
                    anti_sudoku[i][j] = original

        return anti_sudoku

    results = []
    for grid in test_cases:
        anti_sudoku = create_anti_sudoku(grid)
        results.append(anti_sudoku)

    return results

