def solve_anti_sudoku():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    t = int(data[0])
    index = 1

    def is_valid_anti_sudoku(grid):
        # Check rows
        for row in grid:
            if len(set(row)) > 7:
                return False

        # Check columns
        for col in range(9):
            if len(set(grid[row][col] for row in range(9))) > 7:
                return False

        # Check 3x3 blocks
        for block_row in range(0, 9, 3):
            for block_col in range(0, 9, 3):
                block = set()
                for i in range(3):
                    for j in range(3):
                        block.add(grid[block_row + i][block_col + j])
                if len(block) > 7:
                    return False

        return True

    def modify_grid(grid):
        # Try to modify the grid to make it an anti-sudoku
        for i in range(9):
            for j in range(9):
                original_value = grid[i][j]
                for new_value in range(1, 10):
                    if new_value != original_value:
                        grid[i][j] = str(new_value)
                        if is_valid_anti_sudoku(grid):
                            return grid
                grid[i][j] = original_value
        return grid

    results = []
    for _ in range(t):
        grid = [list(data[index + i]) for i in range(9)]
        index += 9
        modified_grid = modify_grid(grid)
        results.append("\n".join("".join(row) for row in modified_grid))

    print("\n\n".join(results))
